const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const text = `${j.title ?? ''} ${j.contentSnippet ?? ''} ${j.content ?? ''}`;
  const textNoDomain = text.replace(/regiebulle/gi, '');
  if (!/\bbulle\b/i.test(textNoDomain)) continue;
  if (!/(2[.,]5|2½|3[.,]5|3½|\b3\s*pi[eè]ce)/i.test(text)) continue;
  if (!/(louer|location|loyer)/i.test(text)) continue;
  const roomsMatch = text.match(/([23])[.,\u00BD]?(5|½)?\s*(?:pi[eè]ces?|pces?)/i) || text.match(/(2[.,]5|2½|3[.,]5|3½)/);
  let rooms = null;
  if (roomsMatch) {
    const raw = roomsMatch[0].replace('½', '.5').replace(',', '.');
    const num = raw.match(/\d+\.?5?/);
    if (num) rooms = parseFloat(num[0]);
  }
  const rentMatch = text.match(/(?:CHF|Fr\.?)[\s:]*([\d'\u2019\u00A0 ]{3,10})/i);
  let rent = null;
  if (rentMatch) {
    const v = parseInt(rentMatch[1].replace(/[^\d]/g, ''), 10);
    if (v >= 300 && v <= 10000) rent = v;
  }
  out.push({ json: {
    source: 'regiebulle',
    source_id: String(j.guid || j.link),
    url: j.link,
    title: j.title,
    rooms,
    rent_gross: rent,
    commune: 'Bulle',
    description: String(j.contentSnippet || j.content || '').slice(0, 2000),
    cross_key: null,
    published_at: j.isoDate || null
  }});
}
return out;
